import {catalog,search,offersFor,alertState,validPrice,readState,toggleFavorite} from './model.js';
import {photos} from './photos.js';
import {observedProductId,observedPrice,alternativeProductPage,usd,parseUsdTarget,readUsdTarget} from './observed.js';
const $=s=>document.querySelector(s),money=n=>Math.round(n).toLocaleString('ko-KR')+'원';
let storage;try{storage=localStorage}catch{}let state=readState(storage),selected='1',view='all',category='전체',days=30,simulations={},timer,detailOpen=false;
let observedMode=true, usdTarget=readUsdTarget(storage);
const isObserved=()=>selected===observedProductId && observedMode;
const price=p=>offersFor(p,simulations[p.id])[0].total;
const history=p=>[...p.history.slice(0,29),price(p)].slice(-days);
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),2500)}
function save(){try{storage.setItem('pricepilot-v1',JSON.stringify(state))}catch{toast('현재 화면에서만 저장됩니다.')}}
function art(p){return photos[p.id]?`<img src="${photos[p.id].url}" alt="${p.brand} ${p.name}" loading="eager">${p.id==='1'?'<span class="photo-caption">브랜드 연출 이미지 · 가격은 50ml 1개 기준</span>':''}`:`<div class="no-photo"><span>${p.brand}</span><small>상품 사진 준비 중</small></div>`}
function renderList(){let items=search($('#search').value,category).filter(p=>view==='all'||state.favorites.includes(p.id));$('#count').textContent=state.favorites.length;$('#list-title').textContent=view==='all'?'지금 눈여겨볼 뷰티':'내가 기다리는 뷰티';$('#result-count').textContent=items.length+'개';$('#products').innerHTML=items.length?items.map(p=>{let avg=p.history.reduce((a,b)=>a+b,0)/p.history.length,change=Math.round((price(p)/avg-1)*100);return `<article class="card"><button class="product-open" data-product="${p.id}"><div class="visual">${art(p)}</div><div class="brand">${p.brand}</div><div class="product-name">${p.name}</div><div class="price-line">${p.id===observedProductId?`<strong>${usd(observedPrice.amount)}</strong>`:`<span class="${change<=0?'down':'up'}">${change<=0?'▼':'▲'} ${Math.abs(change)}%</span> <strong>${money(price(p))}</strong>`}</div><small class="meta">${p.id===observedProductId?"미국 상품가 · 10/15 수동 관측":"30일 평균 대비 · 가상 가격"}</small><div class="delivery">${p.id===observedProductId?"배송비·세금 미확정":"배송비 포함 <span>판매처 3곳</span>"}</div></button><button class="heart" data-favorite="${p.id}" aria-label="관심 상품" aria-pressed="${state.favorites.includes(p.id)}">${state.favorites.includes(p.id)?'♥':'♡'}</button></article>`}).join(''):'<p class="empty">표시할 상품이 없어요. 검색어나 카테고리를 바꿔보세요.</p>'}
function chart(p){const a=history(p),min=Math.min(...a),max=Math.max(...a),avg=a.reduce((x,y)=>x+y,0)/a.length,pad=Math.max(500,(max-min)*.25),lo=min-pad,hi=max+pad,y=v=>190-(v-lo)/(hi-lo)*150,x=i=>12+i*326/(a.length-1);return `<div class="chart-wrap"><svg viewBox="0 0 350 240" role="img" aria-label="최근 ${days}일 배송비 포함 가상 최저가 이력"><title>가격 이력, 단위 원</title>${[max,avg,min].map((v,i)=>`<line x1="12" x2="338" y1="${y(v)}" y2="${y(v)}" stroke="${i===0?'#d8f1df':i===2?'#ffdddd':'#dedfe2'}" stroke-dasharray="3 5"/>`).join('')}<text x="335" y="${y(max)-12}" text-anchor="end" fill="#16ab51">최고 ${money(max)}</text><text x="335" y="${y(min)+23}" text-anchor="end" fill="#f25b55">최저 ${money(min)}</text><polyline points="${a.map((v,i)=>x(i)+','+y(v)).join(' ')}" fill="none" stroke="#f25b55" stroke-width="2.6" stroke-linejoin="round"/><circle cx="338" cy="${y(a.at(-1))}" r="3.5" fill="#f25b55"/><text x="12" y="233">${days-1}일 전</text><text x="175" y="233" text-anchor="middle">${Math.floor(days/2)}일 전</text><text x="338" y="233" text-anchor="end">오늘</text></svg></div><div class="stats">${[['최고가',max,'up','▲'],['평균가',avg,'','−'],['최저가',min,'down','▼']].map(([t,v,c,icon])=>`<div><span><i class="${c}">${icon}</i>${t}</span><strong class="${c}">${money(v)}</strong></div>`).join('')}</div><p class="chart-note">단위: 원 · 일별 배송비 포함 최저가 · 테스트 이력</p>`}
function renderDemoDetail(){const p=catalog.find(p=>p.id===selected),offers=offersFor(p,simulations[p.id]),avg=p.history.reduce((a,b)=>a+b,0)/30,change=Math.round((price(p)/avg-1)*100);$('#detail').innerHTML=`<div class="detail-nav"><button id="back" aria-label="뒤로">←</button><strong>상품 상세</strong><button data-favorite="${p.id}" aria-label="관심 상품">${state.favorites.includes(p.id)?'♥':'♡'}</button></div><div class="detail-product"><div class="detail-art">${art(p)}</div><div class="price-summary"><small>배송비 포함 최저가 · 데모</small><div class="current"><strong>${money(price(p))}</strong><b class="${change<=0?'down':'up'}">${change<=0?'▼':'▲'} ${Math.abs(change)}%</b></div><p class="price-baseline">최근 30일 평균 ${money(avg)} 대비</p><h1>${p.name}</h1><p class="product-meta">${p.brand} · ${p.size}</p><div class="info-chips"><span>판매처 ${offers.length}곳 비교</span><span>배송비 포함</span></div></div></div><section class="analysis-section"><h2>가격 흐름</h2><div class="periods" aria-label="가격 이력 기간">${[7,14,30].map(n=>`<button data-days="${n}" aria-pressed="${n===days}" class="${n===days?'active':''}">${n}일</button>`).join('')}</div>${chart(p)}</section><section class="offer-section"><div class="offer-heading"><h2>판매처 가격 비교 <span>${offers.length}</span></h2><small>총액 낮은순</small></div><p class="offer-context">${p.size} · 동일 상품 · 가상 판매처</p>${offers.map((o,i)=>`<article class="seller-row"><div class="seller-info"><strong>${o.name}${i===0?'<span class="best-tag">최저가</span>':''}</strong><small>${o.shipping===0?'무료배송':'배송비 '+money(o.shipping)} · 예상 ${o.days}</small></div><div class="seller-price"><strong class="${i===0?'down':''}">${money(o.total)}</strong><small>${i===0?'배송비 포함':'최저가 +'+money(o.total-offers[0].total)}</small></div><details class="offer-breakdown"><summary>가격 구성 보기</summary><div>상품 ${money(o.price)} + 배송 ${money(o.shipping)}</div></details></article>`).join('')}<p class="chart-note">실제 판매처 연결 전입니다. 구매는 지원하지 않아요.</p></section><section class="target-section"><h2>나의 목표가</h2><div id="alert-status">${state.targets[p.id]?money(state.targets[p.id])+' · '+alertState(state.targets[p.id],price(p)):'목표 가격을 설정하고 기다려 보세요'}</div>${state.targets[p.id]?'<button id="remove-target">목표가 삭제</button>':''}<details class="simulator"><summary>데모 가격 변경</summary><form id="sim-form"><label for="sim-price">브랜드몰 B 가상 상품 가격</label><div class="inputrow"><input id="sim-price" type="number" min="1" max="10000000" required value="${simulations[p.id]??14000}"><button>적용</button></div></form><button id="sim-reset">원래 가격 복원</button></details></section><div class="detail-actions"><button data-favorite="${p.id}" class="save-action">${state.favorites.includes(p.id)?'♥':'♡'}<small>관심</small></button><button id="set-target" class="primary">목표가 알림 설정</button></div>`;
$('#back').onclick=closeDetail;$('#set-target').onclick=()=>{openTargetDialog(false)};$('#sim-form').onsubmit=e=>{e.preventDefault();let v=$('#sim-price').value;if(!validPrice(v))return;simulations[p.id]=+v;renderDetail();renderList()};$('#sim-reset').onclick=()=>{delete simulations[p.id];renderDetail();renderList()};if($('#remove-target'))$('#remove-target').onclick=()=>{delete state.targets[p.id];save();renderDetail()}}

function openTargetDialog(actual){
  const input=$('#target');
  $('#target-dialog h2').textContent=actual?'원하는 상품가를 저장하세요':'원하는 가격에 알려드릴게요';
  $('#target-dialog>p').textContent=actual?'미국 달러 상품가 기준 · 배송비와 세금 제외':'배송비 포함 목표 가격을 설정하세요.';
  $('#target-dialog .inputrow span').textContent=actual?'USD':'원';
  input.min=actual?'0.01':'1';input.max=actual?'10000':'10000000';input.step=actual?'0.01':'1';input.inputMode=actual?'decimal':'numeric';
  input.value=actual?(usdTarget??''):(state.targets[selected]??'');
  $('#target-dialog .demo-note').textContent=actual?'이 기기에 목표가만 저장합니다. 자동 감시와 푸시는 아직 연결되지 않았어요.':'데모에서는 앱 내 상태만 바뀌며 푸시는 발송하지 않아요.';
  $('#target-dialog').showModal();
}
function observedSwitch(){
  const controls=document.createElement('div');controls.className='periods observed-switch';controls.setAttribute('aria-label','실제 관측과 데모 구분');
  for(const [actual,label] of [[true,'실제 관측 · USD'],[false,'UI 데모 · KRW']]){
    const b=document.createElement('button');b.textContent=label;b.classList.toggle('active',observedMode===actual);b.setAttribute('aria-pressed',String(observedMode===actual));
    b.onclick=()=>{observedMode=actual;renderDetail();};controls.append(b);
  }
  $('#detail .detail-nav').after(controls);
}
function renderObservedDetail(){
  const p=catalog.find(p=>p.id===selected),o=observedPrice;
  $('#detail').innerHTML=`<div class="detail-nav"><button id="back" aria-label="뒤로">←</button><strong>상품 상세</strong><button data-favorite="${p.id}" aria-label="관심 상품">${state.favorites.includes(p.id)?'♥':'♡'}</button></div><div class="detail-product"><div class="detail-art">${art(p)}</div><div class="price-summary"><small>미국 상품가 · 수동 관측</small><div class="current"><strong>${usd(o.amount)}</strong></div><p class="price-baseline">${o.observedOn} 확인 · 자동 갱신 없음</p><h1>${p.name}</h1><p class="product-meta">${p.brand} · ${p.size} · 1개</p><div class="info-chips"><span>USD · 미국 페이지</span><span>배송비·세금 미확정</span></div></div></div><section class="analysis-section"><h2>가격 흐름</h2><div class="stats"><div><span>${o.observedOn}</span><strong>${usd(o.amount)}</strong></div></div><p class="chart-note">관측 1건 · 추세를 판단할 수 없어요. 추가 관측이 쌓이면 같은 자리에서 가격 흐름을 보여드립니다.</p></section><section class="offer-section"><div class="offer-heading"><h2>판매처 가격 비교 <span>2</span></h2><small>총액 비교 대기</small></div><p class="offer-context">${p.size} · 단품 페이지 · 현재 조건은 판매처에서 확인</p><article class="seller-row"><div class="seller-info"><strong>${o.retailer}</strong><small>상품가 확인 · 배송비·세금 미확정</small></div><div class="seller-price"><strong>${usd(o.amount)}</strong><small>${o.observedOn} 수동 관측</small></div><a class="observed-buy" href="${o.url}" target="_blank" rel="noopener noreferrer">Stylevana에서 현재 조건 확인 ↗</a></article><article class="seller-row"><div class="seller-info"><strong>${alternativeProductPage.retailer}</strong><small>상품 페이지 확인 · 미국 가격 미확인</small></div><div class="seller-price"><strong>확인 대기</strong><small>지역별 응답 차이</small></div><a class="observed-buy" href="${alternativeProductPage.url}" target="_blank" rel="noopener noreferrer">iHerb에서 현재 조건 확인 ↗</a></article><p class="chart-note">배송비·세금·재고가 확인되지 않아 최저가로 표시하지 않아요. 수동 확인값은 현재 결제 가격과 다를 수 있습니다. 제휴 링크가 아닙니다.</p></section><section class="target-section"><h2>나의 목표 상품가</h2><div id="alert-status">${usdTarget===null?'원하는 USD 상품가를 저장해 보세요':usd(usdTarget)+' · 과거 관측값 '+(o.amount<=usdTarget?'이하':'초과')+' (현재 도달 여부 미확인)'}</div><p class="chart-note">배송비·세금 제외 · 기기 내 저장 · 자동 감시·푸시 미연결</p>${usdTarget===null?'':'<button id="remove-target">목표가 삭제</button>'}</section><div class="detail-actions"><button data-favorite="${p.id}" class="save-action">${state.favorites.includes(p.id)?'♥':'♡'}<small>관심</small></button><button id="set-target" class="primary">목표 상품가 저장</button></div>`;
  $('#back').onclick=closeDetail;$('#set-target').onclick=()=>openTargetDialog(true);
  if($('#remove-target'))$('#remove-target').onclick=()=>{usdTarget=null;try{storage.removeItem('alimi-observed-us-cosrx-target-v1')}catch{toast('저장소 접근 실패: 현재 화면에서만 삭제됩니다.')}renderDetail();};
}
function renderDetail(){if(isObserved())renderObservedDetail();else renderDemoDetail();if(selected===observedProductId)observedSwitch();}

function closeDetail(){detailOpen=false;$('#detail').hidden=true;$('#browse').hidden=false;window.scrollTo(0,0)}
function openDetail(id){selected=id;detailOpen=true;renderDetail();$('#browse').hidden=true;$('#detail').hidden=false;window.scrollTo(0,0)}
$('#categories').innerHTML=['전체',...new Set(catalog.map(p=>p.category))].map(c=>`<button class="chip ${c==='전체'?'active':''}" data-category="${c}">${c}</button>`).join('');
$('#hero-art').innerHTML=art(catalog[0]);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.product)openDetail(b.dataset.product);if(b.dataset.favorite){toggleFavorite(state,b.dataset.favorite);save();renderList();if(detailOpen)renderDetail()}if(b.dataset.days){days=+b.dataset.days;const y=window.scrollY;renderDetail();window.scrollTo(0,y)}if(b.dataset.category){category=b.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>x.classList.toggle('active',x.dataset.category===category));renderList()}if(b.dataset.view){view=b.dataset.view;document.querySelectorAll('nav [data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===view));renderList();window.scrollTo(0,0)}});
$('#target-form').onsubmit=e=>{e.preventDefault();if(isObserved()){const value=parseUsdTarget($('#target').value);if(value===null){toast('USD 0.01~10,000, 소수 둘째 자리까지 입력하세요');return;}usdTarget=value;let persisted=true;try{storage.setItem('alimi-observed-us-cosrx-target-v1',String(value))}catch{persisted=false;}$('#target-dialog').close();renderDetail();toast(persisted?'미국 상품가 목표를 저장했어요 · 푸시 미연결':'현재 화면에서만 저장됩니다.');return;}if(!validPrice($('#target').value))return;state.targets[selected]=+$('#target').value;save();$('#target-dialog').close();renderDetail();toast('목표 가격을 저장했어요')};$('#search').oninput=renderList;$('#clear').onclick=()=>{$('#search').value='';renderList()};$('#search-tab').onclick=()=>{$('#search').focus();window.scrollTo(0,0)};$('#browse-now').onclick=()=>$('.results').scrollIntoView({behavior:'smooth'});$('#reset').onclick=()=>{if(confirm('관심 상품과 원화 데모 목표가를 초기화할까요? 미국 목표가는 유지됩니다.')){state={favorites:[],targets:{}};save();renderList()}};
document.addEventListener('error',e=>{if(e.target.tagName==='IMG'){const box=document.createElement('div');box.className='no-photo';box.textContent='상품 사진을 불러오지 못했어요';e.target.replaceWith(box)}},true);renderList();

